  ui_story_30400201_17_dialog_content = "Bukan, yang terbaik adalah Wild Turtledoves!",
  ui_story_30400201_18_dialog_content = "<size=45>Mana yang terbaik?</size>",
  ui_story_30400201_19_option_content = "Apa itu Canaries?",
  ui_story_30400201_20_dialog_content = "Canaries itu skuad yang kupimpin. Mereka akan meledakkan apa pun yang kutunjuk dan membuang ke langit siapa pun yang kumau.",
  ui_story_30400201_21_dialog_content = "Mereka selalu menyusup di antara Eclipsite setiap kali menjalankan operasi!",
  ui_story_30400201_22_dialog_content = "Itu karena kami harus memancing mereka,",
