  ui_story_30400201_24_dialog_content = "Karena itu, setiap kali kehabisan bom, mereka harus menunggu kami Wild Turtledoves agar selamat. Menyedihkan sekali!",
  ui_story_30400201_25_dialog_content = "Kupikir kalian semua cukup hebat. Tidak usah bertengkar soal ini, ya?",
  ui_story_30400201_26_option_content = "Apa itu Wild Turtledoves?",
  ui_story_30400201_27_dialog_content = "Wild Turtledoves adalah skuad terbaik Rediesel Wrench. Kami selalu dijadikan mata-mata andalan!",
  ui_story_30400201_28_dialog_content = "Kalian juga selalu yang pertama lari!",
  ui_story_30400201_29_dialog_content = "Itu karena kami harus memastikan rute penyelamatan diri!",
  ui_story_30400201_30_dialog_content = "Itulah alasan kalian selalu membutuhkan perlindungan Canaries. Kalau tidak, saat tertangkap, kalian tidak akan bisa menyelamatkan diri.",
  ui_story_30400201_31_dialog_content = "Kupikir kalian semua cukup hebat. Tidak usah bertengkar soal ini, ya?",
  ui_story_30400201_32_dialog_content = "Aku tidak mau lagi berdebat dengan dia. Aku punya rencana dan pekerjaan lain.",
