  ui_story_30400201_34_dialog_content = "Bukannya kalian berjanji untuk membantuku?",
  ui_story_30400201_35_dialog_content = "Mencari Flashing Bouncing Fellow, 'kan?",
  ui_story_30400201_36_dialog_content = "Yah. Hmm... Bukannya Rabbie baru saja melompat pergi?",
  ui_story_30400201_37_dialog_content = "Apa mungkin dia?",
  ui_story_30400201_38_dialog_content = "Bukan dia, aku!",
  ui_story_30400201_39_dialog_content = "???",
  ui_story_30400201_40_dialog_content = "Aku juga bisa melompat-lompat begini. Lihat! Kenapa kamu tidak mau bilang aku yang terbaik?",
  ui_story_30400201_41_dialog_content = "Yang benar saja.",
  ui_story_30400201_42_dialog_content = "Yang lebih penting, menurut rumor, orang ini selalu berhasil muncul tanpa diketahui.",
