  ui_story_30400201_47_dialog_content = "Jadi, benar kamu?",
  ui_story_30400201_48_dialog_content = "Kenapa, kamu lupa kejadian kemarin?",
  ui_story_30400201_49_dialog_content = "Kemarin...",
  ui_story_30400201_50_dialog_content = "Apa yang kamu lakukan?",
  ui_story_30400201_51_dialog_content = "Akulah yang pertama menemukan PlayerName!",
  ui_story_30400201_52_dialog_content = "Bukan, aku lebih dulu!",
  ui_story_30400201_53_dialog_content = "Tunggu, kenapa kalian mengerubungku? Apa aku sepopuler itu?",
  ui_story_30400201_54_dialog_content = "Sisi depan lebih baik!",
  ui_story_30400201_55_dialog_content = "Sisi belakang lebih baik!",
  ui_story_30400201_56_dialog_content = "Rabbie, jangan berdiri di belakangku tiba-tiba seperti itu!",
  ui_story_30400201_57_dialog_content = "Kalau kamu harus berdiri di belakangku, baiklah. Tapi yang berdiri di depanku, bisa tolong berhenti main bubuk mesiu? Bahaya sekali!",
  ui_story_30400201_58_dialog_content = "Hah? Baiklah, tidak boleh mesiu. Kalau granat boleh?",
  ui_story_30400201_59_dialog_content = "Omong-omong, tolong bantu kami menyelesaikan perdebatan!",
  ui_story_30400201_60_dialog_content = "Menyelesaikan perdebatan? Oke. Apa?",
  ui_story_30400201_61_dialog_content = "Apa mengepung itu lebih ampuh?",
  ui_story_30400201_62_dialog_content = "Atau apa lebih ampuh konfrontasi langsung?",
  ui_story_30400201_63_option_content = "Mungkin konfrontasi langsung.",
  ui_story_30400201_64_dialog_content = "Umumnya, orang memilih menghadapi musuh langsung secara terbuka dan jujur.",
  ui_story_30400201_65_dialog_content = "Nah, 'kan! Mengepung sama saja dengan menunggu orang menangkap ekor imutmu!",
  ui_story_30400201_66_dialog_content = "Namun, pilihan taktik tergantung situasi nyatanya. Terkadang mengepung lebih tepat.",
  ui_story_30400201_67_option_content = "Mungkin mengepung.",
  ui_story_30400201_68_dialog_content = "Kita bicara tentang pertempuran, 'kan?",
  ui_story_30400201_69_dialog_content = "Mengepung bisa jadi taktik efektif saat musuh yang kita hadapi sangat kuat.",
  ui_story_30400201_70_dialog_content = "Tepat! Kamu hanya akan kehabisan bom dan terbunuh kalau langsung menyerang.",
  ui_story_30400201_71_dialog_content = "Itu ada benarnya, tapi menurutku setiap taktik punya keunggulan masing-masing.",
  ui_story_30400201_72_dialog_content = "Kalau begitu, aku punya bom! Bom lebih berguna!",
  ui_story_30400201_73_dialog_content = "Aku punya bor!",
  ui_story_30400201_74_dialog_content = "<size=45>Mana yang menurutmu lebih ampuh?</size>",
  ui_story_30400201_75_option_content = "Mungkin bom.",
  ui_story_30400201_76_dialog_content = "Betul. Aku bisa memakai sebanyak mungkin. Tentu saja bom lebih ampuh!",
  ui_story_30400201_77_dialog_content = "Nah, aku bisa memakai borku selama mungkin. Aku bisa tunjukkan kalau kamu tidak percaya.",
  ui_story_30400201_78_dialog_content = "Jangan mengebor!",
  ui_story_30400201_79_dialog_content = "Aku tidak akan asal mengebor, tidak seperti orang yang asal menjatuhkan bom di mana saja!",
  ui_story_30400201_80_dialog_content = "Siapa?",
  ui_story_30400201_81_dialog_content = "Itu mungkin agak keterlaluan, Joanie.",
  ui_story_30400201_82_option_content = "Mungkin bor.",
  ui_story_30400201_83_dialog_content = "Bor tidak hanya bisa dipakai dalam pertempuran, tapi juga bisa untuk membuat lubang!",
  ui_story_30400201_84_dialog_content = "Apa istimewanya membuat lubang? Bomku juga bisa membuat lubang. Malah lebih besar!",
  ui_story_30400201_85_dialog_content = "Tunggu! Jangan mulai menjatuhkan bom!",
  ui_story_30400201_86_dialog_content = "Jangan khawatir, aku hanya akan menjatuhkan satu atau dua bom supaya kalian lihat.",
  ui_story_30400201_87_dialog_content = "Itu terlalu berbahaya! Kamu nyaris meledakkanku...",
  ui_story_30400201_88_dialog_content = "Itu mungkin agak keterlaluan, Joanie.",
  ui_story_30400201_89_dialog_content = "Aku tahu kalian saling bersaing, tapi sepertinya kamu bisa belajar dari Rabbie sesekali.",
  ui_story_30400201_90_dialog_content = "Dia pintar dan lucu, dan tidak membuat kerusakan di sekitar Colossus.",
  ui_story_30400201_91_dialog_content = "Tidak akan pernah!",
  ui_story_30400201_92_dialog_content = "Payah sekali! Main kabur saja...",
  ui_story_30400201_93_dialog_content = "Oh, aku ingat sekarang! Kamu pergi begitu saja seperti itu kemarin, dan kukira kamu marah.",
  ui_story_30400201_94_dialog_content = "Memang. Aku marah sekali sampai tidak bisa dihibur dengan permen.",
  ui_story_30400201_95_dialog_content = "Jadi, aku akan bertanya sekali lagi: Apa kamu Flashing Bouncing Fellow?",
  ui_story_30400201_96_option_content = "Bagaimana bisa kamu memulai rumor itu?",
  ui_story_30400201_97_dialog_content = "Aku tidak paham bagaimana kamu bisa muncul di pojok tanpa diketahui.",
  ui_story_30400201_98_dialog_content = "Bukan aku.",
  ui_story_30400201_99_dialog_content = "Apa? Tapi kudengar...",
  ui_story_30400201_100_dialog_content = "Aku hanya asal membicarakannya... Lalu semua orang mulai membahasnya.",
  ui_story_30400201_101_dialog_content = "Pintar sekali kamu...",
  ui_story_30400201_102_dialog_content = "Persis seperti rencanaku!",
  ui_story_30400201_103_option_content = "Kenapa kamu melakukannya?",
  ui_story_30400201_104_dialog_content = "Untuk menunjukkan aku pintar!",
  ui_story_30400201_105_dialog_content = "Tapi aku tidak bilang kamu tidak pintar...",
  ui_story_30400201_106_dialog_content = "Dan bagaimana hal ini menunjukkan kamu pintar?",
  ui_story_30400201_107_dialog_content = "Itu menunjukkan bahwa aku tidak hanya bisa melakukan yang Rabbie bisa, tapi juga hal-hal yang dia tidak bisa!",
  ui_story_30400201_108_dialog_content = "Itu juga menunjukkan kepada Rabbie kalau dia sebagian saja dariku! Dan kalau ada yang harus belajar dari yang lain, dialah yang seharusnya belajar dariku!",
  ui_story_30400201_109_dialog_content = "Apa maksudmu dengan dia sebagian saja darimu? Apa yang bisa dia pelajari darimu?",
  ui_story_30400201_110_dialog_content = "\"Sebagian saja dariku\" artinya dia hanya punya beberapa kemampuanku!",
  ui_story_30400201_111_dialog_content = "Apa lagi yang bisa dia lakukan selain melompat dan mundur? Aku jauh lebih jago daripada dia dalam melakukan dua hal itu!",
  ui_story_30400201_112_dialog_content = "Persis seperti rencanaku!",
  ui_story_30400201_113_dialog_content = "Aku bisa muncul dan menghilang dengan cepat!",
  ui_story_30400201_114_dialog_content = "Sebutan itu terdengar lucu. Selain itu, aku tidak menyebabkan kerusakan pada Colossus.",
  ui_story_30400201_115_dialog_content = "Yang paling penting, dia tidak punya sesuatu yang aku punya: bom.",
  ui_story_30400201_116_dialog_content = "Tunggu, kamu hanya mau membuktikan bahwa kamu lebih hebat daripada Rabbie, 'kan?",
  ui_story_30400201_117_dialog_content = "Aku tidak paham kenapa menurutmu sebutan itu lucu, tapi aku paham kenapa kamu melakukannya.",
  ui_story_30400201_118_dialog_content = "Namun, aku juga paham kalau pelakunya Rabbie.",
  ui_story_30400201_119_dialog_content = "Tidak ada bukti yang menunjukkan kamu adalah Flashing Bouncing Fellow yang dibicarakan orang.",
  ui_story_30400201_120_dialog_content = "Baiklah, akan kubuktikan kepadamu!",
  ui_story_30400201_121_dialog_content = "Inilah Boomy Flash Bomb yang tidak akan pernah dimiliki Rabbie!",
  ui_story_30400201_122_dialog_content = "Eh, maaf seharusnya tadi aku setuju saja bahwa kamu benar. Terang sekali! Aku tidak bisa melihat...",
  ui_story_30400601_1_dialog_content = "Panas sekali...",
  ui_story_30400601_2_dialog_content = "Setiap kali kita mendekati Rediesel Desert, rasanya suhu langsung melonjak naik...",
  ui_story_30400601_3_dialog_content = "Mungkin ini hanya imajinasiku?",
  ui_story_30400601_4_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_30400601_5_dialog_content = "Tidak, sepertinya tidak.",
  ui_story_30400601_6_dialog_content = "Keributan besar seperti ini berarti aku pasti berada di tempat yang tepat.",
  ui_story_30400601_7_dialog_content = "Oh? Kenapa lama sekali, PlayerName?",
  ui_story_30400601_8_dialog_content = "Saya menjadi tidak sabar, jadi saya memulai eksperimen tanpa kamu.",
  ui_story_30400601_9_dialog_content = "Eksperimen?",
  ui_story_30400601_10_dialog_content = "Yup! Saya sedang mencoba resep baru hari ini.",
  ui_story_30400601_11_dialog_content = "Bagaimanapun, Wrench menugaskanku untuk mengurus kantin hari ini...",
  ui_story_30400601_12_dialog_content = "Apakah itu sebabnya kamu mengenakan pakaian itu? Sungguh bersemangat, ya?",
  ui_story_30400601_13_dialog_content = "Aku tidak terlalu peduli tentang memasak, jadi aku hanya akan membuat sesuatu untuk mereka.",
  ui_story_30400601_14_dialog_content = "Tapi ketika saya sedang membeli beberapa bahan peledak di pasar gelap, saya menemukan frasa kuno yang digunakan untuk mendeskripsikan makanan—",
  ui_story_30400601_15_dialog_content = "\"Dhuar Dhuar Barbeku.\"",
  ui_story_30400601_16_dialog_content = "Ada ide apa artinya itu?",
  ui_story_30400601_17_dialog_content = "Aku sama sekali tidak tahu.",
  ui_story_30400601_18_dialog_content = "Dari yang saya dapatkan, ini adalah metode memasak yang menggunakan api yang sangat kuat.",
  ui_story_30400601_19_dialog_content = "Ketika saya mengetahui tentang itu, saya tiba-tiba merasa lebih bersemangat tentang memasak.",
  ui_story_30400601_20_dialog_content = "Karena itulah aku memanggilmu ke sini untuk membantu penelitian kecilku.",
  ui_story_30400601_21_dialog_content = "Jadi, apakah kamu perlu saya membaca teks kuno atau semacamnya?",
  ui_story_30400601_22_dialog_content = "Nah, itu akan terlalu merepotkan. Saya hanya perlu kamu menggunakan kekuatanmu pada bahan-bahan saya.",
  ui_story_30400601_23_dialog_content = "Aku perlu tahu apakah mereka lebih memilih diledakkan hingga ke langit atau dihancurkan menjadi sejuta potongan.",
  ui_story_30400601_24_dialog_content = "T-T-Tunggu! Bukankah kamu bilang Wrench yang menugaskanmu mengurus kantin hari ini?",
  ui_story_30400601_25_dialog_content = "Ya, itu berarti saya bisa memilih metode memasak saya sendiri, kan?",
  ui_story_30400601_26_dialog_content = "Dan karena kita sedang membicarakan \"Da Bomb\" di sini, beberapa ledakan seharusnya tidak menjadi masalah!",
  ui_story_30400601_27_dialog_content = "... Saya pikir itu sebenarnya masalah besar!",
  ui_story_30400601_28_dialog_content = "Tidak apa-apa! Lagipula, hal seperti ini sangat normal bagi Rediesel Wrench.",
  ui_story_30400601_29_dialog_content = "Saya sudah menyiapkan semua bahan dan alat masak. Siap menggunakan kekuatanmu, PlayerName?",
  ui_story_30400601_30_dialog_content = "Sepertinya aku tidak punya banyak pilihan...",
  ui_story_30400601_31_dialog_content = "Yah... Ini dia, tak ada apa-apa!",
  ui_story_30400601_32_option_content = "Hubungan telepati dengan bahan-bahan...",
  ui_story_30400601_33_dialog_content = "...",
  ui_story_30400601_34_dialog_content = "Seperti apa saya ini, koki ajaib? Bagaimana saya bisa menggunakan kekuatan psikis saya pada makanan?",
  ui_story_30400601_35_dialog_content = "Tunggu, sayuran murah ini... Kamu beli ini di pasar gelap pagi ini?",
  ui_story_30400601_36_dialog_content = "Sandworm dan dendeng kadal juga...",
  ui_story_30400601_37_dialog_content = "Sepertinya selera Rediesel Wrench masih saja liar seperti biasanya...",
  ui_story_30400601_38_option_content = "Hubungan telepati dengan alat makan...",
  ui_story_30400601_39_dialog_content = "...",
  ui_story_30400601_40_dialog_content = "Seperti apa saya ini, koki ajaib? Bagaimana saya bisa menggunakan kekuatan psikis saya pada makanan?",
  ui_story_30400601_41_dialog_content = "Tunggu, ember ini... Saya cukup yakin itu pernah digunakan untuk menyimpan senjata pada suatu saat.",
  ui_story_30400601_42_dialog_content = "Ini ditutupi dengan penyok dan bekas gosong...",
  ui_story_30400601_43_dialog_content = "Haruskah dia benar-benar menggunakan ini untuk memasak makanan?",
  ui_story_30400601_44_dialog_content = "Jadi, apa keputusannya, PlayerName?",
  ui_story_30400601_45_dialog_content = "Hmm... Saya rasa kita harus melakukan uji coba terlebih dahulu.",
  ui_story_30400601_46_dialog_content = "Mengapa kita tidak mencoba memasak sesuatu sebiasa mungkin?",
  ui_story_30400601_47_dialog_content = "Mengerti! Saya akan menyalakan apinya!",
  ui_story_30400601_48_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_30400601_49_dialog_content = "T-T-Tunggu, apinya terlalu besar! Bagian mana dari \"sebisa mungkin normal\" yang tidak kamu mengerti?",
  ui_story_30400601_50_dialog_content = "Yakin? Karena jika kita benar-benar ingin sukses dengan Boom Boom BBQ...",
  ui_story_30400601_51_dialog_content = "Saya rasa kita akan membutuhkan api yang lebih besar lagi!",
  ui_story_30400601_52_dialog_content = "Apakah kamu keberatan mencampur semuanya dan membuangnya ke dalam ember itu, PlayerName?",
  ui_story_30400601_53_dialog_content = "Dendeng kadal, daging mentah, tomat yang hancur, dan daun sayuran... Apa jenis horor tak terkatakan yang coba kamu buat?",
  ui_story_30400601_54_dialog_content = "Tahu tidak, mungkin ini akan terasa lebih enak jika disajikan sebagai sate.",
  ui_story_30400601_55_dialog_content = "Sepertinya itu bukan ide bagus...",
  ui_story_30400601_56_dialog_content = "Jika tusukan itu meledak dan terbang, mereka akan sama mematikannya seperti granat serpih.",
  ui_story_30400601_57_dialog_content = "Berhenti mencoba memasukkan ledakan ke dalam campuran!",
  ui_story_30400601_58_dialog_content = "Tapi saya dengar bahwa Boom Boom BBQ hanya bisa dibuat dalam kondisi ekstrem.",
  ui_story_30400601_59_dialog_content = "Untuk membuat hidangan terbaik, kita harus memasaknya sampai hampir meledak.",
  ui_story_30400601_60_dialog_content = "Bukankah itu terdengar menarik untukmu? Lagipula, apa itu hidup tanpa sedikit bahaya?",
  ui_story_30400601_61_dialog_content = "Sekarang ke sini dan bantu aku!",
  ui_story_30400601_62_dialog_content = "O-Oke, kalau begitu.",
  ui_story_30400601_63_dialog_content = "(Aku hanya berharap aku bisa bertahan dalam ini...)",
  ui_story_30400601_64_dialog_content = "Wuuss! Ayo kita naikkan suhunya!",
  ui_story_30400601_65_dialog_content = "Duar! Sekarang tambahkan arangnya!",
  ui_story_30400601_66_dialog_content = "Ahhh, tidak ada yang seperti ember penuh cairan merah mendidih untuk mengisi diriku dengan kekuatan!",
  ui_story_30400601_67_dialog_content = "T-T-Tunggu, ada yang tidak beres tentang ember ini!",
  ui_story_30400601_68_dialog_content = "Tunggu, jangan bilang kamu menggunakan ini untuk mencampur bahan peledak!",
  ui_story_30400601_69_dialog_content = "Hah? Sekarang kamu sebutkan... Kamu benar! Ini benar-benar laras peledakku yang bisa diandalkan!",
  ui_story_30400601_70_dialog_content = "Sempurna! Ini seharusnya memberikan hidangan saya tambahan yang sangat spesial!",
  ui_story_30400601_71_dialog_content = "A-aku rasa itu bukan jenis \"pukulan\" yang diinginkan orang dalam makanan mereka!",
  ui_story_30400601_72_dialog_content = "Kita selesai... Joanie's Boom Boom BBQ akan menjadi akhir dari kita semua...",
  ui_story_30400601_73_dialog_content = "Tunggu... Itu dia!",
  ui_story_30400601_74_dialog_content = "Itu adalah hal yang sempurna untuk dikatakan pada saat seperti ini! Duar Duar BBQ!",
  ui_story_30400601_75_dialog_content = "Dan jam berapa itu? Ketika makanannya matang, atau ketika kita semua hampir mati?",
  ui_story_30400601_76_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_30400601_77_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30400601_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30400601_79_dialog_content = "Oh, begitu…",
  ui_story_30400601_80_dialog_content = "Setelah bermain-main sepanjang hari, kau malah meledakkan kantin?",
  ui_story_30400601_81_dialog_content = "Dan sekarang kamu mengharapkan kami untuk memanggang makanan kami sendiri?",
  ui_story_30400601_82_dialog_content = "Apakah ini ide leluconmu, bodoh kau?",
  ui_story_30400601_83_dialog_content = "Hah? Kamu seharusnya bersyukur, tahu! Bukan hanya aku TIDAK meledakkanmu, aku bahkan meninggalkan sesuatu untukmu makan...",
  ui_story_30400601_84_dialog_content = "Apa yang kamu katakan?",
  ui_story_30400601_85_dialog_content = "Kamu mendengarku!",
  ui_story_30400601_86_dialog_content = "Baiklah, berhenti, kalian berdua! Tidak ada yang perlu diperdebatkan di sini.",
  ui_story_30400601_87_dialog_content = "Ketika saya menugaskan Joanie untuk mengurus kantin, saya sudah menduga hal seperti ini akan terjadi.",
  ui_story_30400601_88_dialog_content = "Lagipula, sesekali memang menyenangkan memanggang makanan sendiri. Sekarang mari makan, semua orang!",
  ui_story_30400601_89_dialog_content = "<size=45>Woo-hoo!</size>",
  ui_story_30400601_90_dialog_content = "Argh... Mundur, brengsek! Daging itu milikku!",
  ui_story_30400601_91_dialog_content = "...",
  ui_story_30400601_92_dialog_content = "Uh, maaf tentang itu, PlayerName. Kamu tidak terluka dalam ledakan itu, kan?",
  ui_story_30400601_93_dialog_content = "A-aku baik-baik saja. Hanya sedikit terguncang, kukira.",
  ui_story_30400601_94_dialog_content = "Tetap saja, ada sesuatu yang harus kutanyakan...",
  ui_story_30400601_95_dialog_content = "Ketika kamu meledakkan makanan barusan... Apakah itu disengaja?",
  ui_story_30400601_96_dialog_content = "Tsk... Siapa yang bisa bilang dengan pasti?",
  ui_story_30400601_97_dialog_content = "Aku sudah membuang sebagian besar bahan peledak, tapi aku memilih untuk meninggalkan sedikit di sana.",
  ui_story_30400601_98_dialog_content = "Tentu saja, sesuatu tidak bisa disebut Boom Boom BBQ tanpa sedikit ledakan, 'kan?",
  ui_story_30400601_99_dialog_content = "(Dia tidak menyesal telah melakukan semua ini, bukan?)",
  ui_story_30400601_100_dialog_content = "Akhirnya aku menyadari sesuatu sekarang.",
  ui_story_30400601_101_dialog_content = "Dan apa ya kira-kira itu?",
  ui_story_30400601_102_dialog_content = "Ketika berbicara tentang ledakan, kepribadian sangat penting.",
  ui_story_30400601_103_dialog_content = "Kamu tahu bagaimana biasanya aku mengatakan hal-hal seperti \"bing bang boom,\" dan entah bagaimana selalu terasa seperti aku kehilangan sesuatu.",
  ui_story_30400601_104_dialog_content = "Tapi ketika saya mengatakan \"Dhuar Dhuar BBQ\" tepat sebelum ledakan, rasanya jauh lebih kuat!",
  ui_story_30400601_105_dialog_content = "Karena kamu sangat pandai menciptakan kalimat keren, kira-kira kamu bisa berikan aku beberapa ide lagi?",
  ui_story_30400601_106_dialog_content = "Coba kuingat...",
  ui_story_30400601_107_option_content = "\"Seni itu Ledakan\"!",
  ui_story_30400601_108_dialog_content = "Aku ingat mendengar orang yang suka bom berambut pirang lainnya mengatakan sesuatu seperti itu sebelumnya.",
  ui_story_30400601_109_dialog_content = "Sayangnya, dia akhirnya meledakkan dirinya sendiri.",
  ui_story_30400601_110_dialog_content = "Menggunakan kalimat pendek itu mungkin nasib buruk...",
  ui_story_30400601_111_option_content = "\"Ini dia DUARR\"!",
  ui_story_30400601_112_dialog_content = "Aku pernah mendengar seseorang dengan kepribadian yang mirip mengatakan hal itu sebelumnya.",
  ui_story_30400601_113_dialog_content = "Biasanya dia mengatakan itu sebelum melempar tiga bom miliknya.",
  ui_story_30400601_114_dialog_content = "Sayangnya, dia tidak begitu baik dalam membedakan teman dari musuh.",
  ui_story_30400601_115_dialog_content = "Serius? Suara pria itu sama sekali tidak seperti saya...",
  ui_story_30400601_116_dialog_content = "Sejujurnya, meski... Saya pikir gayamu sudah cukup bagus, Joanie.",
  ui_story_30400601_117_dialog_content = "\"Gayaku\"?",
  ui_story_30400601_118_dialog_content = "Yeah! Kamu ceria, bersemangat, dan kadang bahkan sedikit gila...",
  ui_story_30400601_119_dialog_content = "Saya pikir bom-bommu sudah penuh dengan kepribadianmu.",
  ui_story_30400601_120_dialog_content = "Wow... Saya tidak tahu bahwa kamu begitu memahami ledakanku.",
  ui_story_30400601_121_dialog_content = "Sepertinya kamu memperhatikan semua bom yang telah aku kirimkan padamu!",
  ui_story_30400601_122_dialog_content = "Nih, mau tambah?",
  ui_story_30400601_123_dialog_content = "Tidak, terima kasih. Tapi saya menghargai pemikirannya!",
  ui_story_30400601_124_dialog_content = "Ayo, jangan malu!",
  ui_story_30400601_125_dialog_content = "Aku bilang aku baik-baik saja... Hah? Apa ini?",
  ui_story_30400601_126_dialog_content = "Sate! Baru saja dari panggangan!",
  ui_story_30400601_127_dialog_content = "Kita jarang bertemu, jadi kupikir aku harus mengantarmu kembali ke Colossus dengan perut yang kenyang!",
  ui_story_30400601_128_dialog_content = "Dagingnya lembut dan berair... Tunggu sebentar... Kamu sebenarnya tahu cara memasak, bukan?",
  ui_story_30400601_129_dialog_content = "Yep! Anggap saja ini sebagai hadiahmu karena telah membantu saya menemukan beberapa jawaban baru.",
  ui_story_30400601_130_dialog_content = "Berikutnya saat kamu mengundangku ke Colossus, pastikan aku akan memberikan pertunjukan paling meledak yang pernah ada!",
  ui_story_30400601_131_dialog_content = "Bagus, aku akan pastikan Vice menaruhmu di daftar larangan terbang kami..."
}
